update programs set quirks = replace(quirks, '**Easy alt-path to Silver: $1,000 spent on Frontier purchases** unlocks Silver status without accumulating 10K ESP. Friendly to occasional flyers who put a few flights on the Barclays card.', '**Easy alt-path to Silver: $1,000 spent on Frontier purchases** can unlock Silver status without accumulating 10K ESP - verify with Frontier whether this applies to card spend, direct flight purchases, or both, as the rules can be nuanced. Worth checking flyfrontier.com for current qualification terms.'), last_verified = current_date where slug = 'frontier' and quirks like '%**Easy alt-path to Silver: $1,000 spent on Frontier purchases** unlocks Silver status without accumulating 10K ESP. Friendly to occasional flyers who put a few flights on the Barclays card.%';
